/**
 * Merges an array of [start, end] intervals into a sorted array of non-overlapping intervals.
 * Touching intervals are merged.
 *
 * @param {[number, number][]} intervals - Array of [start, end] integer pairs.
 * @returns {[number, number][]} A new array of merged intervals sorted by start.
 */
export function mergeIntervals(intervals) {
  if (!intervals || intervals.length === 0) {
    return [];
  }

  const sorted = intervals
    .slice()
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [[sorted[0][0], sorted[0][1]]];

  for (let i = 1; i < sorted.length; i++) {
    const [start, end] = sorted[i];
    const last = merged[merged.length - 1];

    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}
