export function createLRU(capacity) {
  const limit = Math.max(0, Math.floor(capacity) || 0);
  const cache = new Map();

  function get(key) {
    if (!cache.has(key)) return undefined;
    const value = cache.get(key);
    cache.delete(key);
    cache.set(key, value);
    return value;
  }

  function put(key, value) {
    if (limit === 0) return;
    if (cache.has(key)) {
      cache.delete(key);
    } else if (cache.size >= limit) {
      cache.delete(cache.keys().next().value);
    }
    cache.set(key, value);
  }

  return { get, put };
}
