export function createLRU(capacity) {
  const limit = Math.max(0, Math.floor(capacity));
  const cache = new Map();

  const head = {};
  const tail = {};
  head.next = tail;
  tail.prev = head;

  function remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  function insertAtFront(node) {
    node.next = head.next;
    node.prev = head;
    head.next.prev = node;
    head.next = node;
  }

  function markAsMostRecent(node) {
    remove(node);
    insertAtFront(node);
  }

  function get(key) {
    const node = cache.get(key);

    if (node === undefined) {
      return undefined;
    }

    markAsMostRecent(node);
    return node.value;
  }

  function put(key, value) {
    if (limit === 0) {
      return;
    }

    const existing = cache.get(key);

    if (existing !== undefined) {
      existing.value = value;
      markAsMostRecent(existing);
      return;
    }

    const node = { key, value, prev: null, next: null };
    cache.set(key, node);
    insertAtFront(node);

    if (cache.size > limit) {
      const leastRecent = tail.prev;
      remove(leastRecent);
      cache.delete(leastRecent.key);
    }
  }

  return { get, put };
}
