export function createLRU(capacity) {
  const map = new Map();
  const head = { prev: null, next: null };
  const tail = { prev: null, next: null };
  head.next = tail;
  tail.prev = head;

  function remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  function addToHead(node) {
    node.next = head.next;
    node.prev = head;
    head.next.prev = node;
    head.next = node;
  }

  function moveToHead(node) {
    remove(node);
    addToHead(node);
  }

  function popTail() {
    const node = tail.prev;
    remove(node);
    return node;
  }

  return {
    get(key) {
      if (!map.has(key)) return undefined;
      const node = map.get(key);
      moveToHead(node);
      return node.value;
    },
    put(key, value) {
      if (map.has(key)) {
        const node = map.get(key);
        node.value = value;
        moveToHead(node);
      } else {
        const node = { key, value, prev: null, next: null };
        map.set(key, node);
        addToHead(node);
        if (map.size > capacity) {
          const lru = popTail();
          map.delete(lru.key);
        }
      }
    },
  };
}
