export function wildcardMatch(s, p) {
  let i = 0;
  let j = 0;
  let star = -1;
  let match = 0;

  while (i < s.length) {
    if (j < p.length && (p[j] === '?' || p[j] === s[i])) {
      i++;
      j++;
    } else if (j < p.length && p[j] === '*') {
      star = j;
      j++;
      match = i;
    } else if (star !== -1) {
      j = star + 1;
      match++;
      i = match;
    } else {
      return false;
    }
  }

  while (j < p.length && p[j] === '*') {
    j++;
  }

  return j === p.length;
}
